package practice;

import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.LongUnaryOperator;

/** Nets a day's trades on the ForkJoinPool it is given, in pieces of at most leafSize(rows) trades. */
public class SettlementJob {

    private final ForkJoinPool pool;
    private final int minRows;
    private final LongUnaryOperator net;
    private final AtomicInteger pieces = new AtomicInteger();

    /**
     * @param pool    the pool the job runs in
     * @param minRows a batch of this many trades or fewer is never cut up
     * @param net     the net amount of one trade
     */
    public SettlementJob(ForkJoinPool pool, int minRows, LongUnaryOperator net) {
        this.pool = pool;
        this.minRows = minRows;
        this.net = net;
    }

    /** The day's net total. */
    public long total(long[] trades) {
        pieces.set(0);
        int leaf = Math.max(1, leafSize(trades.length));
        return pool.invoke(new Part(trades, 0, trades.length, leaf));
    }

    /** How many pieces the last run was netted in. */
    public int pieces() {
        return pieces.get();
    }

    /**
     * The largest number of trades one piece nets. A range of at most this many trades is netted
     * in one piece; a longer one is halved.
     */
    int leafSize(int rows) {
        return Math.max(minRows, rows / (pool.getParallelism() * 32));
    }

    private final class Part extends RecursiveTask<Long> {
        private final long[] trades;
        private final int from, to, leaf;

        Part(long[] trades, int from, int to, int leaf) {
            this.trades = trades;
            this.from = from;
            this.to = to;
            this.leaf = leaf;
        }

        @Override
        protected Long compute() {
            if (to - from <= leaf) {
                pieces.incrementAndGet();
                long s = 0;
                for (int i = from; i < to; i++) s += net.applyAsLong(trades[i]);
                return s;
            }
            int mid = (from + to) >>> 1;
            Part left = new Part(trades, from, mid, leaf);
            left.fork();
            long r = new Part(trades, mid, to, leaf).compute();
            return left.join() + r;
        }
    }
}

package practice;

import java.util.concurrent.ForkJoinPool;
import java.util.function.LongUnaryOperator;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            LongUnaryOperator net = cents -> cents - cents / 100;
            long[] day = new long[64_000];
            long expected = 0;
            for (int i = 0; i < day.length; i++) {
                day[i] = 5_000 + (i * 4_001L) % 700_000;
                expected += net.applyAsLong(day[i]);
            }
            ForkJoinPool staging = new ForkJoinPool(2);
            ForkJoinPool production = new ForkJoinPool(6);
            try {
                SettlementJob onStaging = new SettlementJob(staging, 100, net);
                System.out.println("staging total right: " + (onStaging.total(day) == expected));
                System.out.println("staging pieces (64 to 128 wanted): " + onStaging.pieces());
                SettlementJob onProduction = new SettlementJob(production, 100, net);
                System.out.println("production total right: " + (onProduction.total(day) == expected));
                System.out.println("production pieces (192 to 384 wanted): " + onProduction.pieces());
                onProduction.total(new long[80]);
                System.out.println("pieces for a batch of 80 trades: " + onProduction.pieces());
            } finally {
                staging.shutdownNow();
                production.shutdownNow();
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

